  if(!CalendarEventWrites.allowed(this)){Design.text(body,"Direct saving needs calendar read and write access. You can still use Open calendar on the previous screen without these permissions.",14,400,Design.MUTED);Design.button(body,"Allow direct calendar access",false,this::permission).setEnabled(!s.busy);}
  else if(s.busy&&s.calendars.isEmpty())Design.text(body,"Reading writable calendars…",14,400,Design.MUTED);
  else if(s.calendars.isEmpty()){Design.text(body,"No writable calendars are available. Add a calendar in your calendar app, or use its compose screen.",14,400,Design.MUTED);}
